@router.post("/upload")
async def upload_file(file: UploadFile = File(...)):
    filename = file.filename
    if not (filename.endswith('.pdf') or filename.endswith('.docx')):
        raise HTTPException(status_code=400, detail="Unsupported format. Only PDF and DOCX are allowed.")
    filepath = os.path.join(UPLOAD_FOLDER, filename)
    with open(filepath, "wb") as f:
        f.write(await file.read())
    extracted_text = None
    if filename.endswith('.pdf'):
        extracted_text = extract_text_from_pdf(filepath)
    elif filename.endswith('.docx'):
        extracted_text = extract_text_from_docx(filepath)

    # Send to OpenAI
    prompt = PROMPT + extracted_text
    try:
        client = openai.OpenAI(api_key=openai.api_key)
        response = client.chat.completions.create(
            model="gpt-3.5-turbo",
            messages=[{"role": "user", "content": prompt}]
        )
        ia_result = response.choices[0].message.content
        # Try to parse the result as JSON
        try:
            course_json = json.loads(ia_result)
        except Exception:
            # If not valid JSON, return as text only
            return {"filename": filename, "ia_result": ia_result, "error": "AI result is not valid JSON."}
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Error querying the AI: {str(e)}")

    # Generate scripts and PDFs automatically
    pdf_links = []
    if course_json.get("lessons"):
        for idx, lesson in enumerate(course_json["lessons"], 1):
            lesson_title = lesson.get("lesson", f"Lesson {idx}")
            topics = lesson.get("topics", [])
            script_prompt = (
                f"You are an expert teacher. Generate a highly detailed, specific, and engaging spoken script for the lesson titled '{lesson_title}'. "
                f"Explain the following topics thoroughly, with clear examples, analogies, and step-by-step explanations: {', '.join(topics)}. "
                "The script should be long enough to be read aloud for at least 15 minutes, and should include an introduction, a comprehensive development section, and a thoughtful closing. "
                "Make sure the script is continuous, not summarized, and covers all points in depth."
            )
            try:
                script_response = client.chat.completions.create(
                    model="gpt-3.5-turbo",
                    messages=[{"role": "user", "content": script_prompt}]
                )
                script_text = script_response.choices[0].message.content
            except Exception as e:
                script_text = f"Error generating script: {str(e)}"

            # Generate PDF
            pdf_filename = f"script_{uuid.uuid4().hex[:8]}_{idx}.pdf"
            pdf_path = os.path.join(UPLOAD_FOLDER, pdf_filename)
            c = canvas.Canvas(pdf_path, pagesize=letter)
            width, height = letter
            c.setFont("Helvetica-Bold", 14)
            c.drawString(40, height - 50, f"Lesson Script: {lesson_title}")
            c.setFont("Helvetica", 11)
            y = height - 80
            # Split long lines for PDF rendering
            from reportlab.lib.utils import simpleSplit
            max_width = width - 80
            for line in script_text.split('\n'):
                wrapped_lines = simpleSplit(line.strip(), "Helvetica", 11, max_width)
                for wline in wrapped_lines:
                    if y < 60:
                        c.showPage()
                        y = height - 50
                        c.setFont("Helvetica", 11)
                    c.drawString(40, y, wline)
                    y -= 16
            c.save()
            if idx == 1:
                print(f"First index: {idx}")
            pdf_links.append({"lesson": lesson_title, "pdf": pdf_filename})

    return {
        "filename": filename,
        "course_json": course_json,
        "scripts": pdf_links
    }

HEYGEN_API_KEY = os.getenv("HEYGEN_API_KEY")
HEYGEN_API_URL = "https://api.heygen.com/v2/video/generate"
HEYGEN_STATUS_URL = "https://api.heygen.com/v1/video_status.get"


async def generate_video_from_text(script_text):
    headers = {"X-Api-Key": HEYGEN_API_KEY, "Content-Type": "application/json"}
    data = {
        "video_inputs": [{
            "character": {"type": "avatar", "avatar_id": "Georgia_sitting_office_front", "avatar_style": "normal"},
            "input_text": script_text,
            "voice": {"type": "text", "input_text": script_text, "voice_id": "79cb233e53e04419aa6f86db0ce8b192"}
        }],
        "dimension": {"width": 1280, "height": 720}
    }

    response = requests.post(HEYGEN_API_URL, headers=headers, json=data)
    if response.status_code != 200:
        try:
            error_detail = response.json()
        except Exception:
            error_detail = response.text
        raise HTTPException(status_code=response.status_code, detail=f"Error HeyGen: {error_detail}")

    res_json = response.json()
    video_id = res_json["data"]["video_id"]

    video_url = None
    max_retries = 60 # Wait 10-minute max for video generation (10s * 30)
    for _ in range(max_retries):
        time.sleep(10)
        status_res = requests.get(f"{HEYGEN_STATUS_URL}?video_id={video_id}", headers=headers)
        print(status_res.text)
        if status_res.status_code != 200:
            continue

        try:
            status_json = status_res.json()
        except Exception:
            continue


        status = status_json.get("data", {}).get("status")
        if status == "completed":
            video_url = status_json["data"]["video_url"]
            break
        elif status == "failed":
            raise HTTPException(status_code=500, detail="HeyGen video generation failed.")

    if not video_url:
        return {"message": "Video is taking longer than expected. ID: " + video_id}

    video_filename = f"video_{uuid.uuid4().hex[:8]}.mp4"
    video_path = os.path.join(UPLOAD_FOLDER, video_filename)

    video_data = requests.get(video_url).content
    with open(video_path, "wb") as f:
        f.write(video_data)

    return {
        "filename": video_filename,
        "path": video_path
    }


@router.post("/video1", tags=["Video Generation"])
async def generate_video(file: UploadFile = File(...)):
    """
    Use HeyGen to generate a video and store it in UPLOAD_FOLDER.
    """
    if not file.filename.endswith('.pdf'):
        raise HTTPException(status_code=400, detail="Only PDF files allowed.")

    temp_filename = f"temp_{uuid.uuid4().hex}_{file.filename}"
    temp_filepath = os.path.join(UPLOAD_FOLDER, temp_filename)

    with open(temp_filepath, "wb") as f:
        f.write(await file.read())

    try:
        script_text = extract_text_from_pdf(temp_filepath)
        if not script_text.strip():
            raise HTTPException(status_code=400, detail="The PDF is empty.")

        video = await generate_video_from_text(script_text)
        return {
            "message": "Video generated and saved successfully.",
            "video_filename": video["filename"],
            "video_path": video["path"]
        }

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
    finally:
        if os.path.exists(temp_filepath):
            os.remove(temp_filepath)

def extract_text_from_pdf(filepath):
    text = ""
    with pdfplumber.open(filepath) as pdf:
        for page in pdf.pages:
            text += page.extract_text() or ""
    return text

def extract_text_from_docx(filepath):
    doc = docx.Document(filepath)
    return '\n'.join([p.text for p in doc.paragraphs])
